Build_vFiltroChecklist.inputs:
@if(
  and(
    empty(outputs('Sala_Normalizada')),
    empty(outputs('DataIni_Normalizada')),
    empty(outputs('DataFim_Normalizada'))
  ),
  'ID gt 0',
  trim(concat(
    if(empty(outputs('Sala_Normalizada')), '', concat('Sala0 eq ''', replace(outputs('Sala_Normalizada'), '''', ''''''), '''')),
    if(and(not(empty(outputs('Sala_Normalizada'))), not(empty(outputs('DataIni_Normalizada')))), ' and ', ''),
    if(empty(outputs('DataIni_Normalizada')), '', concat('DataInspecao ge datetime''', outputs('DataIni_Normalizada'), 'T00:00:00Z''')),
    if(and(or(not(empty(outputs('Sala_Normalizada'))), not(empty(outputs('DataIni_Normalizada')))), not(empty(outputs('DataFim_Normalizada')))), ' and ', ''),
    if(empty(outputs('DataFim_Normalizada')), '', concat('DataInspecao le datetime''', outputs('DataFim_Normalizada'), 'T23:59:59Z'''))
  ))
)

