RespostaDisplay.inputs:
@if(
  equals(outputs('RespostaNorm'), 'conforme'),
  'Conforme',
  if(
    or(equals(outputs('RespostaNorm'), 'não conforme'), equals(outputs('RespostaNorm'), 'nao conforme')),
    'Não Conforme',
    if(
      or(equals(outputs('RespostaNorm'), 'não se aplica'), equals(outputs('RespostaNorm'), 'nao se aplica')),
      'Não se Aplica',
      outputs('RespostaNorm')
    )
  )
)

StatusCellStyle.inputs:
@if(
  equals(outputs('RespostaNorm'), 'conforme'),
  'background-color:#e6f4ea;color:#137333;font-weight:600;',
  if(
    or(equals(outputs('RespostaNorm'), 'não conforme'), equals(outputs('RespostaNorm'), 'nao conforme')),
    'background-color:#fce8e6;color:#c5221f;font-weight:600;',
    'background-color:#f8f9fa;color:#5f6368;'
  )
)

StatusNCStyle.inputs:
@if(
  or(
    equals(toLower(coalesce(item()?['StatusNC']?['Value'], item()?['StatusNCResponsavel']?['Value'], item()?['StatusNC'], '')), 'encerrada'),
    equals(toLower(coalesce(item()?['StatusNC']?['Value'], item()?['StatusNCResponsavel']?['Value'], item()?['StatusNC'], '')), 'concluído'),
    equals(toLower(coalesce(item()?['StatusNC']?['Value'], item()?['StatusNCResponsavel']?['Value'], item()?['StatusNC'], '')), 'concluido')
  ),
  'background-color:#e6f4ea;color:#137333;font-weight:600;',
  if(
    equals(toLower(coalesce(item()?['StatusNC']?['Value'], item()?['StatusNCResponsavel']?['Value'], item()?['StatusNC'], '')), 'em tratamento'),
    'background-color:#fff4ce;color:#8a6d00;font-weight:600;',
    'background-color:#fce8e6;color:#c5221f;font-weight:600;'
  )
)
